import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose accented characters (e.g. õ -> o + combining mark),
    # then drop the combining marks to get the base letter.
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))

    out = []
    prev_dash = True  # start "in a dash run" so leading separators are dropped
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_dash = False
        elif not prev_dash:
            # collapse any run of non-alphanumeric chars into a single dash
            out.append('-')
            prev_dash = True

    if out and out[-1] == '-':
        out.pop()

    return ''.join(out)

